<style>
@page{margin:9mm}
*{box-sizing:border-box}
body{margin:0;font-family:"DejaVu Sans",sans-serif;color:#182230;font-size:11px;line-height:1.65;background:#fff}
.paper{min-height:270mm;border:4px solid #071E45;padding:4px;position:relative}
.paper-inner{min-height:262mm;border:1px solid #D79A21;padding:24px 31px 19px;position:relative;overflow:hidden}
.paper-inner:before{content:"";position:absolute;right:-95px;top:-120px;width:260px;height:260px;border:42px solid rgba(215,154,33,.055);border-radius:50%}
.letter-head{width:100%;border-collapse:collapse;border-bottom:3px double #071E45;padding-bottom:13px;margin-bottom:17px}
.letter-head td{vertical-align:middle;padding-bottom:13px}
.letter-logo-cell{width:74px}.letter-logo{width:61px;height:61px;object-fit:contain}.letter-logo-fallback{width:58px;height:58px;border-radius:13px;background:#071E45;color:white;text-align:center;line-height:58px;font-size:23px;font-weight:800}
.letter-school{font-family:"DejaVu Serif",serif;font-size:20px;font-weight:800;color:#071E45;text-transform:uppercase;letter-spacing:.4px}
.letter-motto{font-family:"DejaVu Serif",serif;font-size:9px;font-style:italic;color:#A46E0B;margin-top:3px}.letter-meta{font-size:8.5px;color:#667085;margin-top:4px;line-height:1.45}
.ref-row{width:100%;border-collapse:collapse;margin-bottom:16px}.ref-row td{font-size:8.5px;color:#667085}.ref-row td:last-child{text-align:right}.ref-row strong{color:#071E45}
.document-title{text-align:center;margin:0 0 19px}.document-title span{display:inline-block;background:#071E45;color:white;border-bottom:4px solid #D79A21;padding:8px 28px 7px;font-family:"DejaVu Serif",serif;font-size:16px;font-weight:800;text-transform:uppercase;letter-spacing:1.4px}
.recipient{margin-bottom:15px;font-family:"DejaVu Serif",serif;font-size:11px;line-height:1.6}.recipient strong{font-size:13px;color:#071E45}
.salutation{font-family:"DejaVu Serif",serif;font-size:12px;font-weight:bold;color:#071E45;margin:9px 0}
.body-text{font-family:"DejaVu Serif",serif;font-size:11.2px;text-align:justify;line-height:1.75;margin-bottom:11px;white-space:pre-line}
.body-text strong,.body-text b{color:#071E45}
.offer-details{width:100%;border-collapse:collapse;margin:16px 0;background:#F8FAFC;border:1px solid #DDE4EE}
.offer-details td{padding:7px 10px;border-bottom:1px solid #E4E9F0;font-size:10px}.offer-details tr:last-child td{border:0}.offer-details td:first-child{width:31%;font-weight:800;color:#071E45;background:#F2F5F9;text-transform:uppercase;font-size:8px;letter-spacing:.06em}
.acceptance-note{padding:10px 12px;background:#FFFAEB;border-left:4px solid #D79A21;color:#694A08;font-size:9.5px;margin:15px 0}
.sign-table{width:100%;border-collapse:collapse;margin-top:27px}.sign-table td{width:38%;vertical-align:bottom;text-align:center;padding:0 10px;font-size:9px}.sign-table td.seal-cell{width:24%}
.sign-line{border-top:1px solid #071E45;padding-top:5px;font-weight:800;color:#071E45}.seal{width:67px;height:67px;border:3px double rgba(7,30,69,.7);border-radius:50%;margin:auto;text-align:center;padding-top:18px;color:#071E45;font-size:7px;font-weight:800;text-transform:uppercase;transform:rotate(-6deg)}
.letter-footer{position:absolute;left:31px;right:31px;bottom:14px;border-top:1px solid #E1E6ED;padding-top:7px;text-align:center;color:#7C8798;font-size:7.5px;letter-spacing:.02em}
</style>
